using System;using System.IO;using UnityEngine;using IslandGame;using Newtonsoft.Json.Linq;
public static class VerifyComboPlayback {
 public static object Run(){var view=UnityEngine.Object.FindFirstObjectByType<Battle3DView>();var battle=UnityEngine.Object.FindFirstObjectByType<NativeBattle>();if(!Application.isPlaying||!view.HeroTarget)throw new Exception("Live hero required");var catalog=JObject.Parse(Resources.Load<TextAsset>("HeroContactProfile").text);float maximum=0;int samples=0;var rig=battle.CameraRig;
 foreach(int face in new[]{-1,1})foreach(string action in new[]{"attack1","attack2","attack3"})for(int i=39;i<=(action=="attack3"?93:69);i++){float phase=i/120f;var hero=new JObject{{"action",action},{"motion",new JObject{{"kind","attack"},{"attackId",77},{"start",0},{"duration",.55}}}};var state=new JObject{{"hero",hero}};rig.SetViewMode(ViewMode.Side25D);rig.ResetPose();rig.PrepareTransition(.02f);view.HeroDepth=0;view.Planar=false;view.PreparePresentation(state,hero,phase*.55f,rig);view.Draw("hero",action,0,0,face,"verify",phase*.55f,.55f,.22f,"attack",.02f,phase*.55f);var f=catalog["lowAttacks"][action]["frames"][i];var a=new Vector3((float)f[2]*face,(float)f[1],-(float)f[0])/100;var b=new Vector3((float)f[5]*face,(float)f[4],-(float)f[3])/100;float error=Mathf.Max(Vector3.Distance(a,view.HeroWeaponBase),Vector3.Distance(b,view.HeroWeaponTip));maximum=Mathf.Max(maximum,error);samples++;if(error>.005f)throw new Exception(action+" face="+face+" phase="+phase+" blade error="+error);}
 var buffer=new CombatSnapshotBuffer();int checks=0;for(int i=0;i<45;i++){float now=i*.01f;float snap=Mathf.Floor(now*10)/10;var h=new JObject{{"x",0},{"y",5000},{"elevation",0},{"airHeight",0},{"action","attack1"},{"motion",new JObject{{"kind","attack"},{"start",0},{"duration",.55},{"attackId",1}}}};var raw=new JObject{{"id","buffer"},{"room",0},{"routeStage","mount"},{"elapsed",snap},{"hero",h},{"mobs",new JArray(new JObject{{"id",1},{"x",42},{"y",5000},{"hp",snap>=.3f?30:90}})},{"fx",snap>=.3f?new JArray(new JObject{{"target","mob1"},{"contactAt",.22},{"attackId",1}}):new JArray()}};var shown=buffer.Sample(raw,now,true);if(buffer.Time<.22f&&(int)shown["mobs"][0]["hp"]!=90)throw new Exception("early damage");checks++;}
 var result=new JObject{{"bladeSamples",samples},{"maximumBladeErrorMeters",maximum},{"bufferChecks",checks},{"scope","3 attacks, both side facings, active contact frames"}};File.WriteAllText("C:/Users/SHK/combo-deploy-20261109/evidence/contact-parity.json",result.ToString());return result;
